import { GCSymbolView } from './GCSymbolView';
import { GCService } from './GCService';
import { GRReelView } from '../../slots/GRReelView';
import gsap, { TweenLite, Expo } from 'gsap';
import { CascadeState, GCReelEvent, IGCRSettings } from './types';
import { GRUtils } from '../../slots';

export class GCReelView<GenericSymbol extends GCSymbolView> extends GRReelView<GenericSymbol> {

    public eventFire: GCReelEvent;
    public hideUnusedSymbols: boolean = false;

    protected _service: GCService;
    private _isReelCascading: boolean;

    private _localSettings: IGCRSettings = {
        fallTime: () => {
            const fallTime = this._service.cascadeSettings.cascadeFallSettings.fallTime;
            const length = this._service.model.onScreenReels.length;
            return GRUtils.fillArrayOrValue(fallTime, length)[this.reelIndex];
        },
        fallOffset: () => {
            const fallOffset = this._service.cascadeSettings.cascadeFallSettings.fallOffset;
            const length = this._service.model.onScreenReels.length;
            return GRUtils.fillArrayOrValue(fallOffset, length)[this.reelIndex];
        },
    };

    constructor(SymbolType: { new(): GenericSymbol }, service: GCService, reelSize: number, reelIndex: number) {
        super(SymbolType, service, reelSize, reelIndex);
        this.addEvents();
    }

    protected buildReel(symbolType: { new(): GenericSymbol }): void {
        super.buildReel(symbolType);
        //apply callback to symbol eventfire event
        for (const symbol of this._symbols) {
            symbol.eventFire.symbolEvent.REMOVE_FROM_CASCADE = () => {
                symbol.symbolData.removedFromCascade = true;
                this.onRemoveSymbol();
            };
        }
    }

    private beginReelCascade(): void {
        //check if there are symbols to remove 
        const locationSymbols: GenericSymbol[] = this.getLocationSymbols(true);
        if (locationSymbols.length === 0) {
            this._isReelCascading = false;
            this._service.model.invalidateSingleCascadeState(this.reelIndex, CascadeState.NOT_CASCADING);
            return;
        }
        this._isReelCascading = true;
        this.interactiveChildren = false;

        // call to remove symbol 
        for (const symbol of locationSymbols) {
            symbol.removeFromCascade();
        }
    }

    private onRemoveSymbol(): void {
        // check symbols have been removed
        const locationSymbols: GenericSymbol[] = this.getLocationSymbols(false);
        for (const $symbol of locationSymbols) {
            if (!$symbol.symbolData.removedFromCascade) {
                return;
            }
        }

        const tease = this._service.cascadeSettings.cascadeTease;
        const teaseActive = tease.newSymbolsDelay > 0 || tease.reelStaggerDelay > 0;

        if (teaseActive) {
            // Only return non-removed symbols to cascade (alpha = 1).
            // Removed symbols stay hidden (alpha = 0 from removeFromCascade) until their tease delay.
            const removedSymbolSet = new Set(locationSymbols);
            this._symbols.forEach((symbol: GenericSymbol) => {
                if (!removedSymbolSet.has(symbol)) {
                    symbol.returnToCascade();
                }
            });
        } else {
            // Original behavior: return all symbols to cascade immediately
            this._symbols.forEach((symbol: GenericSymbol) => {
                symbol.returnToCascade();
            });
        }

        // begin cascading 
        if (this._service.model.cascadeState[this.reelIndex] !== CascadeState.FALLING) {
            this._service.model.invalidateSingleCascadeState(this.reelIndex, CascadeState.FALLING);
            this.triggerCascadeFall();
        }
    }

    private removeDuplicateLocations(positions: number[]): number[] {
        const uniquePositions = [...new Set(positions)];
        return uniquePositions;
    }

    private getLocationSymbols(removeDuplicates: boolean): GenericSymbol[] {
        const reelLocations: number[] = this._service.model.cascadeLocations[this.reelIndex];
        const symbolIndexArray: number[] = removeDuplicates ? this.removeDuplicateLocations(reelLocations) : reelLocations;
        const symbols: GenericSymbol[] = [];
        for (const $symbolIndex of symbolIndexArray) {
            symbols.push(this._symbols[$symbolIndex]);
        }
        return symbols;
    }

    public triggerCascadeFall(): void {
        const symbolsToMove: GenericSymbol[] = this.getLocationSymbols(true);
        const reelOutcome: number[] = this._service.model.cascadeOutcome[this.reelIndex];
        const tease = this._service.cascadeSettings.cascadeTease;
        const teaseActive = tease.newSymbolsDelay > 0 || tease.reelStaggerDelay > 0;
        const numberOfRemovedSymbols = symbolsToMove.length;

        if (symbolsToMove.length > 0) {
            this._symbols[0].y -= this._localSettings.fallOffset();
        }
        // set position and move symbol to front of
        symbolsToMove.forEach((symbol: GenericSymbol, $offsetIndex: number) => {
            this._symbols.splice(this._symbols.indexOf(symbol), 1);
            this._symbols.unshift(symbol);
            this._symbolHolder.setChildIndex(symbol, 0);
            const offset = -($offsetIndex + 1);
            symbol.y = (this.getTargetPositionY(offset) - this._localSettings.fallOffset());
        });
        // set skin
        for (let $symbolIndex: number = 0; $symbolIndex < reelOutcome.length; $symbolIndex++) {
            const skin: number = reelOutcome[$symbolIndex];
            const offsetSymbolIndex = $symbolIndex + this._topOffset;
            const symbol = this._symbols[offsetSymbolIndex];
            symbol.symbolData.skin = skin;
            symbol.symbolData.index = $symbolIndex;
            symbol.setAnimationSkin();
        }

        if (this.hideUnusedSymbols) {
            this.symbols.forEach((symbol, index) => {
                if ((this._topOffset > 0 && index < this._topOffset) || (this._bottomOffset > 0 && index >= this._symbols.length - this._bottomOffset)) {
                    symbol.visible = false;
                } else {
                    symbol.visible = true;
                }
            });
        }

        //get the index of the lowest block that falls
        let maxFallIndex: number = -1;
        this._service.model.cascadeLocations[this.reelIndex].forEach((value) => {
            if (value > maxFallIndex) {
                maxFallIndex = value;
            }
        });

        if (!teaseActive) {
            // Original behavior: all symbols fall together with continuous block stagger
            this._symbols.forEach((symbol: GenericSymbol, $offsetIndex: number) => {
                if ($offsetIndex <= maxFallIndex) {
                    const delayTime = (maxFallIndex - $offsetIndex) * this._service.cascadeSettings.cascadeBlockFallDelay;
                    const targetYPosition: number = this.getTargetPositionY($offsetIndex);
                    TweenLite.to(symbol, this._localSettings.fallTime(), {
                        y: targetYPosition, ease: Expo.easeIn, delay: delayTime, onComplete: () => {
                            symbol.onCascadeLand();
                        }
                    });
                }
            });

            const totalFallDelayTime = maxFallIndex * this._service.cascadeSettings.cascadeBlockFallDelay + this._localSettings.fallTime();
            gsap.delayedCall(totalFallDelayTime, () => {
                this._isReelCascading = false;
                this.eventFire.reelEffect.CASCADE_EFFECT();
                this._service.model.invalidateSingleCascadeState(this.reelIndex, CascadeState.NOT_CASCADING);
            });
        } else {
            // Tease behavior: existing on-screen symbols fall first, then new symbols drop in after delay.
            const firstOnScreenIndex = numberOfRemovedSymbols + this._topOffset;

            // Hide all off-screen symbols (removed + topBuffer)
            for (let i = 0; i < firstOnScreenIndex; i++) {
                this._symbols[i].alpha = 0;
            }

            // Build sorted index lists for each phase
            // Phase 1 is the initial fall of on screen symbols
            // Phase 2 is the delayed fall of the new symbols.
            const existingSymbolIndices: number[] = [];
            const newSymbolIndices: number[] = [];
            for (let i = 0; i <= maxFallIndex; i++) {
                if (i < firstOnScreenIndex) {
                    newSymbolIndices.push(i);
                } else {
                    existingSymbolIndices.push(i);
                }
            }

            // Calculate how long existing on-screen symbols take to finish falling (local to this reel)
            const existingCount = existingSymbolIndices.length;
            const existingSymbolsFallDuration = existingCount > 0
                ? ((existingCount - 1) * this._service.cascadeSettings.cascadeBlockFallDelay) + this._localSettings.fallTime()
                : 0;

            // Compute the global max existing fall duration across ALL reels so that Phase 2 starts
            // at the same moment on every reel, regardless of how many existing symbols each reel has.
            let globalMaxExistingFallDuration = 0;

            this._service.model.cascadeLocations.forEach((reelLocations: number[]) => {
                if (!reelLocations || reelLocations.length === 0) { return; }

                const reelRemovedCount = new Set(reelLocations).size;
                const reelMaxFallIndex = Math.max(...reelLocations);
                const reelFirstOnScreenIndex = reelRemovedCount + this._topOffset;
                const reelExistingCount = Math.max(0, reelMaxFallIndex - reelFirstOnScreenIndex + 1);
                const reelFallDuration = reelExistingCount > 0
                    ? ((reelExistingCount - 1) * this._service.cascadeSettings.cascadeBlockFallDelay) + this._localSettings.fallTime()
                    : 0;
                if (reelFallDuration > globalMaxExistingFallDuration) {
                    globalMaxExistingFallDuration = reelFallDuration;
                }
            });

            // Phase 1
            existingSymbolIndices.forEach((symbolArrayIndex: number, i: number) => {
                const symbol = this._symbols[symbolArrayIndex];
                const delayTime = (existingCount - 1 - i) * this._service.cascadeSettings.cascadeBlockFallDelay;
                const targetYPosition: number = this.getTargetPositionY(symbolArrayIndex);

                TweenLite.to(symbol, this._localSettings.fallTime(), {
                    y: targetYPosition, ease: Expo.easeIn, delay: delayTime, onComplete: () => {
                        symbol.onCascadeLand();
                    }
                });
            });

            // Phase 2 delay: wait for the slowest reel's Phase 1 to finish, then add the tease gap.
            const newSymbolsBaseDelay = globalMaxExistingFallDuration + tease.newSymbolsDelay;
            const reelStagger = tease.reelStaggerDelay * this.reelIndex;
            const newCount = newSymbolIndices.length;

            // Phase 2
            newSymbolIndices.forEach((symbolArrayIndex: number, i: number) => {
                const symbol = this._symbols[symbolArrayIndex];
                const blockStagger = (newCount - 1 - i) * this._service.cascadeSettings.cascadeBlockFallDelay;
                const delayTime = newSymbolsBaseDelay + reelStagger + blockStagger;
                const targetYPosition: number = this.getTargetPositionY(symbolArrayIndex);

                TweenLite.to(symbol, this._localSettings.fallTime(), {
                    y: targetYPosition, ease: Expo.easeIn, delay: delayTime,
                    onStart: () => {
                        symbol.symbolData.removedFromCascade = false;
                        symbol.alpha = 1;
                    },
                    onComplete: () => {
                        symbol.onCascadeLand();
                    }
                });
            });

            // Calculate total cascade completion time
            const newSymbolsCompleteDuration = newCount > 0
                ? newSymbolsBaseDelay + reelStagger + ((newCount - 1) * this._service.cascadeSettings.cascadeBlockFallDelay) + this._localSettings.fallTime()
                : 0;
            const totalFallDelayTime = Math.max(existingSymbolsFallDuration, newSymbolsCompleteDuration);

            gsap.delayedCall(totalFallDelayTime, () => {
                this._isReelCascading = false;
                this.eventFire.reelEffect.CASCADE_EFFECT();
                this._service.model.invalidateSingleCascadeState(this.reelIndex, CascadeState.NOT_CASCADING);
            });
        }
    }

    private defaultCascadeBounceEffect(): void {
        const startY: number = this._symbolHolder.y;
        TweenLite.to(this._symbolHolder.position, this._service.cascadeSettings.cascadeBounceSettings.duration * 0.5, {
            y: startY + this._service.cascadeSettings.cascadeBounceSettings.offset, onComplete: () => {
                TweenLite.to(this._symbolHolder.position, this._service.cascadeSettings.cascadeBounceSettings.duration * 0.5, { y: startY });
            },
        });
    }

    private onCascadeState$(state: number[]): void {
        if (state[this.reelIndex] === CascadeState.REMOVAL) {
            if (!this._isReelCascading) {
                this.eventFire.reelEvent.ON_BEGIN_SPIN_BEFORE_TICK();
                this.beginReelCascade();
            }
        }
    }

    protected addBindings(): void {
        super.addBindings();
        this._service.model.bindToValue(this, () => this._service.model.cascadeState, () => this.onCascadeState$);
    }

    private addEvents(): void {
        Object.assign(this.eventFire.reelEffect, { CASCADE_EFFECT: () => this.defaultCascadeBounceEffect });
    }
}